custom_css:
:root {
  --xal-void: #07050c;
  --xal-panel: rgba(12, 8, 18, 0.78);
  --xal-gold: #c4a25a;
  --xal-gold-dim: rgba(196, 162, 90, 0.38);
  --xal-lilac: #b48cff;
  --xal-ice: #7ec8ff;
}

body, #sheld, #chat {
  font-family: "Palatino Linotype", Palatino, "Book Antiqua", Georgia, serif;
}

#sheld, .drawer-content, #right-nav-panel, #left-nav-panel,
#rm_print_characters_block, #form_sheld {
  border-color: var(--xal-gold-dim) !important;
}

.drawer-content, .inline-drawer-content {
  background: var(--xal-panel) !important;
  box-shadow: 0 0 24px rgba(80, 30, 120, 0.18);
}

.menu_button, .menu_button_icon {
  border: 1px solid var(--xal-gold-dim) !important;
  background: rgba(20, 12, 32, 0.7) !important;
  color: #e8dcc0 !important;
  border-radius: 4px !important;
}
.menu_button:hover, .menu_button_icon:hover {
  border-color: var(--xal-gold) !important;
  color: #fff4d4 !important;
  box-shadow: 0 0 10px rgba(180, 140, 80, 0.25);
}

#send_but, #send_form {
  border-color: var(--xal-gold-dim) !important;
}
#send_textarea {
  background: rgba(8, 6, 14, 0.72) !important;
  color: #efe6d4 !important;
  border: 1px solid var(--xal-gold-dim) !important;
}

.mes {
  border-radius: 6px;
}
.mes .mes_text {
  line-height: 1.55;
}
.mes[is_user="true"] {
  box-shadow: inset 0 0 0 1px rgba(196, 162, 90, 0.16);
}
.mes:not([is_user="true"]) {
  box-shadow: inset 0 0 0 1px rgba(140, 90, 200, 0.16);
}

q, .mes_text q {
  color: #c9b0ff !important;
}

::-webkit-scrollbar { width: 8px; }
::-webkit-scrollbar-track { background: #0a0710; }
::-webkit-scrollbar-thumb {
  background: linear-gradient(#3a2658, #c4a25a);
  border-radius: 8px;
}

#rm_print_characters_block .character_select,
.avatar img {
  border: 1px solid var(--xal-gold-dim) !important;
}

.toastr {
  background: rgba(12, 8, 18, 0.92) !important;
  border: 1px solid var(--xal-gold-dim) !important;
  color: #efe6d4 !important;
}

#top-bar, #top-settings-holder {
  background: rgba(7, 5, 12, 0.55) !important;
}

.character_name, .ch_name {
  color: #f0e2b8 !important;
}

#xal-hud, .xal-hud, [id*="xal"] {
  border-color: var(--xal-gold) !important;
}
